import{u as l,j as e}from"./index-DFKQ5FvX.js";import{c,L as n}from"./vendor-react-BN1EXeZX.js";import"./vendor-sentry-Bn_sck6K.js";const d={pt:{updated:"11 de agosto de 2026",updatedLabel:"Última atualização",back:"← Voltar",print:"Imprimir / Guardar PDF",also:"Consulte também:",tagline:"— e-Market Oil & Gas · Angola / África",termsLink:"Termos de Uso",privacyLink:"Política de Privacidade",terms:{title:"TERMOS DE USO",sections:[{n:1,title:"O que é a KIXIMA",paras:["A KIXIMA é uma plataforma digital B2B (e-marketplace) de procurement para o setor de Oil & Gas em Angola, que liga empresas compradoras a empresas fornecedoras credenciadas, com um fluxo de compra estruturado (ordem de compra, aprovação, fatura, pagamento em prazo definido e receção) e mecanismos de confiança, incluindo credenciamento documental, apólices de seguro e registo de auditoria.","A KIXIMA não é parte nos contratos de compra e venda celebrados entre compradores e fornecedores: é a infraestrutura que os suporta."]},{n:2,title:"Elegibilidade e cadastro",paras:["A plataforma destina-se exclusivamente a empresas (pessoas coletivas) e aos seus utilizadores autorizados. O cadastro exige documentos de credenciamento verdadeiros e válidos (certidão comercial, alvará, licenças aplicáveis) e, para fornecedores, apólice de seguro válida. Quem regista a empresa declara ter poderes para a vincular a estes Termos.","A KIXIMA pode aprovar, rejeitar ou suspender cadastros com base na análise de credenciamento (due diligence), sem que disso resulte direito a indemnização."]},{n:3,title:"Contas e segurança",paras:["As credenciais de acesso são pessoais e intransmissíveis. A empresa é responsável pelos atos praticados através das contas dos seus utilizadores. Devem ser-nos comunicados de imediato acessos não autorizados. Recomendamos senhas fortes e a ativação da autenticação de dois fatores quando disponível."]},{n:4,title:"Fluxo de compra e pagamento",paras:["O fluxo padrão é: emissão de ordem de compra pelo comprador; aprovação interna; aceitação pelo fornecedor (que gera a fatura da plataforma); pagamento pelo comprador dentro do prazo definido (por omissão, 7 dias); execução/entrega; e confirmação de receção. Divergências na receção são registadas e resolvidas na plataforma (aceitação da entrega ou reposição).","Os comprovativos de pagamento carregados e as confirmações de receção fazem fé no histórico da plataforma. As faturas geradas pela KIXIMA são documentos de suporte da operação na plataforma; a emissão de faturas fiscalmente válidas nos termos da legislação angolana é responsabilidade de cada fornecedor."]},{n:5,title:"Taxa KIXIMA",paras:['Pela utilização da plataforma é devida pelo fornecedor uma taxa de serviço ("Taxa KIXIMA"), calculada por fatura processada segundo a fórmula publicada na plataforma. O extrato de taxas está disponível na conta do fornecedor. A KIXIMA pode rever a fórmula, com comunicação prévia razoável.']},{n:6,title:"Obrigações das empresas utilizadoras",paras:["As empresas comprometem-se a: fornecer informação verdadeira e mantê-la atualizada; publicar apenas produtos/serviços que podem legalmente fornecer; cumprir as ordens de compra aceites e os prazos assumidos; não usar a plataforma para fins ilícitos, fraudulentos ou anticoncorrenciais; e respeitar direitos de propriedade intelectual de terceiros."]},{n:7,title:"Conteúdos e catálogo",paras:["Cada fornecedor é responsável pelos conteúdos que publica (descrições, preços, imagens, certificações). A KIXIMA pode remover conteúdos que violem estes Termos ou a lei. Os preços apresentados são da responsabilidade do fornecedor."]},{n:8,title:"Suspensão e cessação",paras:["A KIXIMA pode suspender ou encerrar contas em caso de violação destes Termos, suspeita fundada de fraude, incumprimento reiterado ou exigência legal. A empresa pode cessar a utilização a qualquer momento, mantendo-se devidos os valores e obrigações pendentes; os registos de operações são conservados nos termos da Política de Privacidade e da lei."]},{n:9,title:"Responsabilidade",paras:['A plataforma é disponibilizada "tal como está". Na máxima medida permitida por lei, a KIXIMA não responde por lucros cessantes nem por danos indiretos decorrentes de negócios entre utilizadores, sem prejuízo da responsabilidade que não possa ser legalmente excluída. Nada nestes Termos limita a responsabilidade por dolo.']},{n:10,title:"Lei aplicável e foro",paras:["Estes Termos regem-se pela lei da República de Angola. Para qualquer litígio emergente é competente o foro da Comarca de Luanda, com renúncia expressa a qualquer outro."]},{n:11,title:"Alterações",paras:["Podemos atualizar estes Termos; as alterações relevantes serão comunicadas na plataforma com antecedência razoável. A utilização continuada após a entrada em vigor constitui aceitação."]}]},privacy:{title:"POLÍTICA DE PRIVACIDADE",sections:[{n:1,title:"Responsável pelo tratamento",paras:["A KIXIMA é a responsável pelo tratamento dos dados pessoais recolhidos na plataforma, nos termos da Lei n.º 22/11, de 17 de junho (Lei da Proteção de Dados Pessoais de Angola). Contacto: através do módulo de Ajuda/Suporte da plataforma."]},{n:2,title:"Dados que tratamos",paras:["Dados de conta: nome, email profissional, telefone, função/perfil, empresa a que pertence e credenciais (a senha é guardada apenas de forma cifrada e irreversível).","Dados da empresa: identificação fiscal, documentos de credenciamento, apólices, dados bancários para pagamentos.","Dados de operação: ordens de compra, faturas, pagamentos e comprovativos, confirmações de receção, mensagens de suporte, registos de auditoria (quem fez o quê, quando e de que endereço IP).","Dados técnicos: registos de acesso e erros, necessários à segurança e ao funcionamento."]},{n:3,title:"Finalidades e fundamentos",paras:["Tratamos os dados para: prestar o serviço contratado (execução do contrato); cumprir obrigações legais (contabilísticas, fiscais e de conservação de registos); garantir a segurança, prevenir fraude e manter o trilho de auditoria (interesse legítimo); e comunicar notificações operacionais da plataforma.","Não vendemos dados pessoais nem os usamos para publicidade de terceiros."]},{n:4,title:"Partilha de dados",paras:["Os dados de operação são visíveis às contrapartes do negócio na medida do necessário (ex.: o fornecedor vê a ordem e o comprovativo de pagamento do comprador; o comprador vê os dados do fornecedor). Usamos subcontratantes técnicos para alojamento, base de dados, armazenamento de ficheiros, envio de email e monitorização de erros, vinculados a deveres de confidencialidade e segurança. Podemos divulgar dados quando exigido por lei ou autoridade competente."]},{n:5,title:"Transferências internacionais",paras:["Alguns subcontratantes técnicos podem alojar dados fora de Angola (ex.: centros de dados na União Europeia). Nesses casos, procuramos garantias adequadas de proteção equivalente."]},{n:6,title:"Conservação",paras:["Conservamos os dados enquanto a conta estiver ativa e, após o encerramento, pelos prazos exigidos por lei ou necessários à defesa de direitos — em particular, os registos de operações financeiras e o trilho de auditoria, que por natureza são conservados de forma imutável.","Os prazos concretos por categoria de dados estão publicados e são os mesmos que a plataforma aplica automaticamente: pode consultá-los a qualquer momento em /api/retencao. As notificações já lidas são eliminadas ao fim de 180 dias e os convites de funcionário expirados ou cancelados ao fim de 90 dias."]},{n:7,title:"Segurança",paras:["Aplicamos medidas técnicas e organizativas adequadas: cifragem em trânsito (HTTPS), senhas com hash forte, controlo de acessos por perfil, registo de auditoria imutável, isolamento por empresa (multi-tenant) e monitorização de erros. Nenhum sistema é 100% seguro; incidentes relevantes serão comunicados nos termos da lei."]},{n:8,title:"Os seus direitos",paras:["Nos termos da Lei n.º 22/11, tem direito de acesso, retificação, atualização e, quando aplicável, eliminação dos seus dados pessoais, bem como de oposição ao tratamento em certas circunstâncias.","Não precisa de pedir: em Configurações → Segurança pode descarregar tudo o que a plataforma sabe sobre si, num único ficheiro, e pode eliminar os seus dados pessoais sem passar por ninguém. A eliminação exige a sua senha porque é irreversível e fecha a conta.","Os registos de operações e o trilho de auditoria são conservados por obrigação legal, mas deixam de o identificar: o seu nome é substituído e a ligação à sua pessoa desaparece. Para o resto, ou dúvidas, use o módulo de Ajuda/Suporte."]},{n:9,title:"Cookies e tecnologias locais",paras:["A plataforma usa apenas armazenamento local estritamente necessário ao funcionamento (ex.: manter a sessão iniciada). Não usamos cookies de publicidade nem rastreamento de terceiros."]},{n:10,title:"Alterações a esta política",paras:["Podemos atualizar esta Política; as alterações relevantes serão comunicadas na plataforma. A data da última atualização consta no topo do documento."]}]}},en:{updated:"11 August 2026",updatedLabel:"Last updated",back:"← Back",print:"Print / Save as PDF",also:"See also:",tagline:"— Oil & Gas e-Market · Angola / Africa",termsLink:"Terms of Use",privacyLink:"Privacy Policy",terms:{title:"TERMS OF USE",sections:[{n:1,title:"What KIXIMA is",paras:["KIXIMA is a B2B digital procurement platform (e-marketplace) for the Oil & Gas sector in Angola, connecting buying companies to accredited supplier companies through a structured purchasing flow (purchase order, approval, invoice, payment within a defined term and receipt) and trust mechanisms, including documentary accreditation, insurance policies and an audit trail.","KIXIMA is not a party to the purchase and sale contracts entered into between buyers and suppliers: it is the infrastructure that supports them."]},{n:2,title:"Eligibility and registration",paras:["The platform is intended exclusively for companies (legal entities) and their authorised users. Registration requires true and valid accreditation documents (commercial certificate, permit, applicable licences) and, for suppliers, a valid insurance policy. Whoever registers the company declares that they have authority to bind it to these Terms.","KIXIMA may approve, reject or suspend registrations based on the accreditation review (due diligence), without any right to compensation arising from that decision."]},{n:3,title:"Accounts and security",paras:["Access credentials are personal and non-transferable. The company is responsible for acts carried out through its users’ accounts. Unauthorised access must be reported to us immediately. We recommend strong passwords and enabling two-factor authentication where available."]},{n:4,title:"Purchasing and payment flow",paras:["The standard flow is: issuance of a purchase order by the buyer; internal approval; acceptance by the supplier (which generates the platform invoice); payment by the buyer within the defined term (7 days by default); execution/delivery; and confirmation of receipt. Discrepancies on receipt are recorded and resolved on the platform (acceptance of the delivery or replacement).","Uploaded payment proofs and receipt confirmations are authoritative in the platform history. Invoices generated by KIXIMA are supporting documents for the operation on the platform; issuing tax-valid invoices under Angolan legislation is the responsibility of each supplier."]},{n:5,title:"KIXIMA Fee",paras:['A service fee (the "KIXIMA Fee") is payable by the supplier for use of the platform, calculated per processed invoice according to the formula published on the platform. The fee statement is available in the supplier account. KIXIMA may revise the formula with reasonable prior notice.']},{n:6,title:"Obligations of user companies",paras:["Companies undertake to: provide true information and keep it up to date; publish only products/services they may lawfully supply; fulfil accepted purchase orders and the terms undertaken; not use the platform for unlawful, fraudulent or anti-competitive purposes; and respect third-party intellectual property rights."]},{n:7,title:"Content and catalog",paras:["Each supplier is responsible for the content it publishes (descriptions, prices, images, certifications). KIXIMA may remove content that breaches these Terms or the law. Displayed prices are the supplier’s responsibility."]},{n:8,title:"Suspension and termination",paras:["KIXIMA may suspend or close accounts in the event of a breach of these Terms, well-founded suspicion of fraud, repeated non-compliance or legal requirement. A company may cease using the platform at any time, with outstanding amounts and obligations remaining due; operation records are retained under the Privacy Policy and the law."]},{n:9,title:"Liability",paras:['The platform is provided "as is". To the fullest extent permitted by law, KIXIMA is not liable for lost profits or indirect damages arising from business between users, without prejudice to liability that cannot lawfully be excluded. Nothing in these Terms limits liability for wilful misconduct.']},{n:10,title:"Governing law and jurisdiction",paras:["These Terms are governed by the law of the Republic of Angola. The courts of the Comarca de Luanda have jurisdiction over any dispute arising, with express waiver of any other."]},{n:11,title:"Changes",paras:["We may update these Terms; material changes will be communicated on the platform with reasonable advance notice. Continued use after they take effect constitutes acceptance."]}]},privacy:{title:"PRIVACY POLICY",sections:[{n:1,title:"Data controller",paras:["KIXIMA is the controller of the personal data collected on the platform, under Law no. 22/11 of 17 June (Angolan Personal Data Protection Law). Contact: through the platform’s Help/Support module."]},{n:2,title:"Data we process",paras:["Account data: name, business email, phone, role/profile, the company you belong to and credentials (the password is stored only in an encrypted, irreversible form).","Company data: tax identification, accreditation documents, policies, bank details for payments.","Operational data: purchase orders, invoices, payments and payment proofs, receipt confirmations, support messages, audit records (who did what, when and from which IP address).","Technical data: access and error logs, required for security and operation."]},{n:3,title:"Purposes and legal bases",paras:["We process data to: provide the contracted service (performance of the contract); comply with legal obligations (accounting, tax and record retention); ensure security, prevent fraud and maintain the audit trail (legitimate interest); and send operational platform notifications.","We do not sell personal data nor use it for third-party advertising."]},{n:4,title:"Data sharing",paras:["Operational data is visible to the counterparties of the business as necessary (e.g. the supplier sees the order and the buyer’s payment proof; the buyer sees the supplier’s details). We use technical processors for hosting, database, file storage, email delivery and error monitoring, bound by confidentiality and security duties. We may disclose data when required by law or a competent authority."]},{n:5,title:"International transfers",paras:["Some technical processors may host data outside Angola (e.g. data centres in the European Union). In such cases we seek adequate safeguards providing equivalent protection."]},{n:6,title:"Retention",paras:["We retain data while the account is active and, after closure, for the periods required by law or necessary to defend rights — in particular financial operation records and the audit trail, which by their nature are retained immutably.","The specific periods per data category are published and are the same ones the platform applies automatically: you can read them at any time at /api/retencao. Notifications you have already read are deleted after 180 days, and expired or cancelled employee invitations after 90 days."]},{n:7,title:"Security",paras:["We apply appropriate technical and organisational measures: encryption in transit (HTTPS), strongly hashed passwords, role-based access control, an immutable audit trail, per-company isolation (multi-tenant) and error monitoring. No system is 100% secure; material incidents will be reported as required by law."]},{n:8,title:"Your rights",paras:["Under Law no. 22/11, you have the right of access, rectification, updating and, where applicable, erasure of your personal data, as well as objection to processing in certain circumstances.","You do not have to ask: under Settings → Security you can download everything the platform knows about you in a single file, and you can erase your personal data without going through anyone. Erasure asks for your password because it is irreversible and closes the account.","Operation records and the audit trail are retained by legal obligation, but they stop identifying you: your name is replaced and the link to you disappears. For anything else, or for questions, use the Help/Support module."]},{n:9,title:"Cookies and local technologies",paras:["The platform uses only local storage strictly necessary for operation (e.g. keeping you signed in). We do not use advertising cookies or third-party tracking."]},{n:10,title:"Changes to this policy",paras:["We may update this Policy; material changes will be communicated on the platform. The date of the last update appears at the top of the document."]}]}},fr:{updated:"11 août 2026",updatedLabel:"Dernière mise à jour",back:"← Retour",print:"Imprimer / Enregistrer en PDF",also:"Consultez également :",tagline:"— e-Market Oil & Gas · Angola / Afrique",termsLink:"Conditions d'utilisation",privacyLink:"Politique de confidentialité",terms:{title:"CONDITIONS D'UTILISATION",sections:[{n:1,title:"Qu'est-ce que KIXIMA",paras:["KIXIMA est une plateforme numérique B2B (e-marketplace) d'approvisionnement pour le secteur Oil & Gas en Angola, qui relie les entreprises acheteuses aux entreprises fournisseurs accréditées, avec un flux d'achat structuré (bon de commande, approbation, facture, paiement dans un délai défini et réception) et des mécanismes de confiance, dont l'accréditation documentaire, les polices d'assurance et une piste d'audit.","KIXIMA n'est pas partie aux contrats d'achat et de vente conclus entre acheteurs et fournisseurs : elle est l'infrastructure qui les supporte."]},{n:2,title:"Éligibilité et enregistrement",paras:["La plateforme est destinée exclusivement aux entreprises (personnes morales) et à leurs utilisateurs autorisés. L'enregistrement exige des documents d'accréditation véridiques et valides (certificat commercial, permis, licences applicables) et, pour les fournisseurs, une police d'assurance valide. La personne qui enregistre l'entreprise déclare avoir le pouvoir de l'engager au titre des présentes Conditions.","KIXIMA peut approuver, rejeter ou suspendre des enregistrements sur la base de l'analyse d'accréditation (due diligence), sans qu'il en résulte un droit à indemnisation."]},{n:3,title:"Comptes et sécurité",paras:["Les identifiants d'accès sont personnels et incessibles. L'entreprise est responsable des actes accomplis via les comptes de ses utilisateurs. Tout accès non autorisé doit nous être signalé immédiatement. Nous recommandons des mots de passe forts et l'activation de l'authentification à deux facteurs lorsqu'elle est disponible."]},{n:4,title:"Flux d'achat et de paiement",paras:["Le flux standard est le suivant : émission d'un bon de commande par l'acheteur ; approbation interne ; acceptation par le fournisseur (qui génère la facture de la plateforme) ; paiement par l'acheteur dans le délai défini (7 jours par défaut) ; exécution/livraison ; et confirmation de réception. Les écarts constatés à la réception sont enregistrés et résolus sur la plateforme (acceptation de la livraison ou remplacement).","Les justificatifs de paiement téléversés et les confirmations de réception font foi dans l'historique de la plateforme. Les factures générées par KIXIMA sont des documents de support de l'opération sur la plateforme ; l'émission de factures fiscalement valides au regard de la législation angolaise relève de la responsabilité de chaque fournisseur."]},{n:5,title:"Frais KIXIMA",paras:["L'utilisation de la plateforme donne lieu à des frais de service dus par le fournisseur (« Frais KIXIMA »), calculés par facture traitée selon la formule publiée sur la plateforme. Le relevé des frais est disponible dans le compte du fournisseur. KIXIMA peut réviser la formule moyennant un préavis raisonnable."]},{n:6,title:"Obligations des entreprises utilisatrices",paras:["Les entreprises s'engagent à : fournir des informations véridiques et les tenir à jour ; ne publier que des produits/services qu'elles peuvent légalement fournir ; honorer les bons de commande acceptés et les délais convenus ; ne pas utiliser la plateforme à des fins illicites, frauduleuses ou anticoncurrentielles ; et respecter les droits de propriété intellectuelle de tiers."]},{n:7,title:"Contenus et catalogue",paras:["Chaque fournisseur est responsable des contenus qu'il publie (descriptions, prix, images, certifications). KIXIMA peut retirer les contenus qui enfreignent les présentes Conditions ou la loi. Les prix affichés relèvent de la responsabilité du fournisseur."]},{n:8,title:"Suspension et résiliation",paras:["KIXIMA peut suspendre ou fermer des comptes en cas de violation des présentes Conditions, de soupçon fondé de fraude, de manquement répété ou d'exigence légale. L'entreprise peut cesser d'utiliser la plateforme à tout moment, les montants et obligations en cours restant dus ; les enregistrements des opérations sont conservés conformément à la Politique de confidentialité et à la loi."]},{n:9,title:"Responsabilité",paras:["La plateforme est fournie « en l'état ». Dans toute la mesure permise par la loi, KIXIMA n'est pas responsable des pertes de bénéfices ni des dommages indirects résultant des affaires entre utilisateurs, sans préjudice de la responsabilité qui ne peut être légalement exclue. Rien dans les présentes Conditions ne limite la responsabilité en cas de faute intentionnelle."]},{n:10,title:"Droit applicable et juridiction",paras:["Les présentes Conditions sont régies par le droit de la République d'Angola. Tout litige relève de la compétence de la Comarca de Luanda, avec renonciation expresse à toute autre juridiction."]},{n:11,title:"Modifications",paras:["Nous pouvons mettre à jour les présentes Conditions ; les modifications importantes seront communiquées sur la plateforme avec un préavis raisonnable. La poursuite de l'utilisation après leur entrée en vigueur vaut acceptation."]}]},privacy:{title:"POLITIQUE DE CONFIDENTIALITÉ",sections:[{n:1,title:"Responsable du traitement",paras:["KIXIMA est responsable du traitement des données personnelles collectées sur la plateforme, au titre de la Loi n.º 22/11 du 17 juin (loi angolaise sur la protection des données personnelles). Contact : via le module Aide/Support de la plateforme."]},{n:2,title:"Données que nous traitons",paras:["Données de compte : nom, e-mail professionnel, téléphone, fonction/profil, entreprise d'appartenance et identifiants (le mot de passe n'est conservé que sous forme chiffrée et irréversible).","Données de l'entreprise : identification fiscale, documents d'accréditation, polices d'assurance, coordonnées bancaires pour les paiements.","Données opérationnelles : bons de commande, factures, paiements et justificatifs, confirmations de réception, messages de support, enregistrements d'audit (qui a fait quoi, quand et depuis quelle adresse IP).","Données techniques : journaux d'accès et d'erreurs, nécessaires à la sécurité et au fonctionnement."]},{n:3,title:"Finalités et bases légales",paras:["Nous traitons les données pour : fournir le service contracté (exécution du contrat) ; respecter des obligations légales (comptables, fiscales et de conservation) ; garantir la sécurité, prévenir la fraude et maintenir la piste d'audit (intérêt légitime) ; et envoyer des notifications opérationnelles de la plateforme.","Nous ne vendons pas de données personnelles et ne les utilisons pas à des fins publicitaires de tiers."]},{n:4,title:"Partage des données",paras:["Les données opérationnelles sont visibles des contreparties de l'affaire dans la mesure nécessaire (ex. : le fournisseur voit la commande et le justificatif de paiement de l'acheteur ; l'acheteur voit les données du fournisseur). Nous recourons à des sous-traitants techniques pour l'hébergement, la base de données, le stockage de fichiers, l'envoi d'e-mails et la surveillance des erreurs, tenus à des obligations de confidentialité et de sécurité. Nous pouvons divulguer des données lorsque la loi ou une autorité compétente l'exige."]},{n:5,title:"Transferts internationaux",paras:["Certains sous-traitants techniques peuvent héberger des données hors d'Angola (ex. : centres de données dans l'Union européenne). Dans ces cas, nous recherchons des garanties adéquates assurant une protection équivalente."]},{n:6,title:"Conservation",paras:["Nous conservons les données tant que le compte est actif et, après sa fermeture, pendant les durées exigées par la loi ou nécessaires à la défense de droits — en particulier les enregistrements d'opérations financières et la piste d'audit, conservés par nature de façon immuable.","Les durées précises par catégorie de données sont publiées et sont celles que la plateforme applique automatiquement : vous pouvez les consulter à tout moment sur /api/retencao. Les notifications déjà lues sont supprimées au bout de 180 jours et les invitations de collaborateur expirées ou annulées au bout de 90 jours."]},{n:7,title:"Sécurité",paras:["Nous appliquons des mesures techniques et organisationnelles appropriées : chiffrement en transit (HTTPS), mots de passe hachés de façon robuste, contrôle d'accès par profil, piste d'audit immuable, isolement par entreprise (multi-tenant) et surveillance des erreurs. Aucun système n'est sûr à 100 % ; les incidents importants seront communiqués conformément à la loi."]},{n:8,title:"Vos droits",paras:["Au titre de la Loi n.º 22/11, vous disposez d'un droit d'accès, de rectification, de mise à jour et, le cas échéant, d'effacement de vos données personnelles, ainsi que d'opposition au traitement dans certaines circonstances.","Vous n'avez pas besoin de le demander : dans Paramètres → Sécurité, vous pouvez télécharger tout ce que la plateforme sait de vous dans un seul fichier, et effacer vos données personnelles sans passer par personne. L'effacement demande votre mot de passe car il est irréversible et ferme le compte.","Les enregistrements d'opérations et la piste d'audit sont conservés par obligation légale, mais ils cessent de vous identifier : votre nom est remplacé et le lien vers vous disparaît. Pour le reste, ou en cas de question, utilisez le module Aide/Support."]},{n:9,title:"Cookies et technologies locales",paras:["La plateforme n'utilise qu'un stockage local strictement nécessaire au fonctionnement (ex. : maintien de la session ouverte). Nous n'utilisons ni cookies publicitaires ni traceurs tiers."]},{n:10,title:"Modifications de cette politique",paras:["Nous pouvons mettre à jour la présente Politique ; les modifications importantes seront communiquées sur la plateforme. La date de dernière mise à jour figure en haut du document."]}]}}};function u({n:o,title:i,paras:r}){return e.jsxs("section",{style:{marginTop:18},children:[e.jsxs("h2",{style:{fontSize:14.5,margin:"0 0 6px"},children:[o,". ",i]}),e.jsx("div",{style:{display:"grid",gap:8},children:r.map((a,s)=>e.jsx("p",{children:a},s))})]})}function h({kind:o}){const i=c(),{lang:r}=l(),a=d[r]||d.pt,s=o==="privacidade"?a.privacy:a.terms;return e.jsxs("div",{className:"doc-page",children:[e.jsxs("div",{className:"doc-toolbar no-print",children:[e.jsx("button",{className:"btn btn-ghost",onClick:()=>i(-1),children:a.back}),e.jsx("button",{className:"btn btn-accent",onClick:()=>window.print(),children:a.print})]}),e.jsxs("div",{className:"pdoc-sheet",children:[e.jsxs("header",{className:"pdoc-head",children:[e.jsxs("div",{className:"pdoc-tagline",style:{fontSize:15},children:[e.jsx("strong",{children:"KIXIMA"})," ",a.tagline]}),e.jsxs("div",{className:"pdoc-tagline",children:[a.updatedLabel,": ",a.updated]})]}),e.jsx("div",{className:"pdoc-titlebar",children:e.jsx("h1",{children:s.title})}),e.jsx("div",{style:{fontSize:13,lineHeight:1.6},children:s.sections.map(t=>e.jsx(u,{n:t.n,title:t.title,paras:t.paras},t.n))}),e.jsxs("p",{className:"pdoc-muted no-print",style:{marginTop:22,fontSize:11},children:[a.also," ",e.jsx(n,{to:"/termos",children:a.termsLink})," · ",e.jsx(n,{to:"/privacidade",children:a.privacyLink})]})]})]})}export{h as default};
